export type Win7IconName = keyof typeof WIN7_ICON_SIZES;

export function win7Icon(name: Win7IconName, size: number): string {
  const sizes: readonly number[] = WIN7_ICON_SIZES[name];
  const pick = sizes.find((s) => s >= size) ?? sizes[sizes.length - 1];
  return `/icons/win7/${name}-${pick}.png`;
}
